          }
          cutoff = elementDetail.slice(0, minIndex);

          //console.log(parsedStepFile[cutoff].elementName);

          freqObj[e][parsedStepFile[cutoff].elementName] = cutoff;
        }

        ////////////////////////////////////////////////////
      });
